select p.id, v.name, v.tier
from (
  values
    ('Pre-facelift'::text, 'Reference'::text, 1::integer),
    ('Facelift'::text, 'Reference'::text, 1::integer),
    ('Pre-facelift'::text, 'Style'::text, 2::integer),
    ('Facelift'::text, 'Style'::text, 2::integer),
    ('Pre-facelift'::text, 'Xcellence'::text, 3::integer),
    ('Facelift'::text, 'Xcellence'::text, 3::integer),
    ('Pre-facelift'::text, 'FR'::text, 3::integer),
    ('Facelift'::text, 'FR'::text, 3::integer)
) as v(phase_label, name, tier)
join (
  select cp.id, cp.phase_label
  from catalog_phases cp
  join catalog_models cm on cm.id = cp.model_id
  join catalog_brands cb on cb.id = cm.brand_id
  where cb.name = 'SEAT' and cm.name = 'Arona' and cp.generation_code = 'KJ7'
) as p on p.phase_label = v.phase_label
where not exists (
  select 1 from catalog_trims ct where ct.phase_id = p.id and ct.name = v.name
);

